using System;
using System.IO;
using System.Linq;
using UnityEngine;
using AnimalArchive.Voyage;
public static class VoyageV10Verification {
 static int checks;static void Check(bool b,string label){checks++;if(!b)throw new Exception("V10 FAILED: "+label);}
 public static void All(){VoyageVerification.Run();VoyageV8Verification.Run();VoyageV9Verification.Run();Run();}
 static VoyageModel Stock(VoyageConfig cfg,int level){var m=new VoyageModel(cfg);m.state.levels[2]=level;m.state.spawnClock=999;m.state.workers[0].rest=999;int target=64;while(m.state.active.Count<target){m.state.spawnClock=0;m.Tick(.001f);}m.state.spawnClock=999;foreach(var p in m.state.active){p.dockLevel=level;p.berth=-1;p.admitted=false;p.age=0;p.calm=100;p.x=.55f+(p.id%5)*.02f;p.y=.64f+(p.id%4)*.03f;p.tx=p.x;p.ty=p.y;}return m;}
 public static void Run(){checks=0;var cfg=JsonUtility.FromJson<VoyageConfig>(File.ReadAllText("Assets/Resources/Voyage/config.json"));
  var report=new System.Text.StringBuilder("V10 actual C# model checks\n");long first=0,last=0;
  for(int lv=0;lv<=5;lv++){var m=Stock(cfg,lv);bool bounded=true,moving=true;for(int t=0;t<100;t++){var old=m.state.active.Where(p=>p.admitted).ToDictionary(p=>p.id,p=>p.boarding);m.Tick(.1f);bounded&=m.state.active.Count(p=>p.berth>=0)<=3*(lv+1)&&m.state.active.Count(p=>p.admitted)<=3*(lv+1);foreach(var p in m.state.active)if(old.TryGetValue(p.id,out var a))moving&=p.boarding>a;}
   Check(bounded,"real concurrency Lv"+lv);Check(moving,"no waiting on bridge Lv"+lv);Check(m.state.active.Where(p=>p.berth>=0).Select(p=>p.berth).Distinct().Count()==m.DockOccupied,"one reservation per lane Lv"+lv);if(lv==0)first=m.state.boarded;if(lv==5)last=m.state.boarded;report.AppendLine("Dock Lv"+lv+": "+m.state.boarded+" arrivals in 10s, slots "+m.DockCapacity);}
  var drain=Stock(cfg,5);drain.state.mode=1;foreach(var p in drain.state.active){p.x=.54f;p.y=.73f;p.waitTime=1;}for(int i=0;i<180;i++)drain.Tick(.1f);Check(drain.state.active.Count==0,"holding pockets reclaim free berths during final drain");
  Check(last>first*3,"wide entrance delivers materially higher throughput");
  var unattended=Stock(cfg,0);var operated=Stock(cfg,0);var entrance=VoyageModel.RampFoot(0,0);operated.state.guideX=entrance.x;operated.state.guideY=entrance.y;for(int t=0;t<200;t++){unattended.Tick(.1f);operated.Tap(entrance.x,entrance.y);operated.Tick(.1f);}Check(operated.state.boarded>unattended.state.boarded*1.4f,"manual dock guidance clears a saturated queue faster");report.AppendLine("20s saturated dock: automatic "+unattended.state.boarded+", manual "+operated.state.boarded);
  var commitment=Stock(cfg,0);foreach(var p in commitment.state.active){p.x=.18f;p.y=.72f;p.calm=.01f;p.heading=true;p.waitTime=0;}for(int t=0;t<900;t++)commitment.Tick(.1f);Check(commitment.state.active.Count==0,"all guided animals retain destination after calm expires");
  var stale=Stock(cfg,0);foreach(var p in stale.state.active)p.berth=0;stale.Tick(.1f);Check(stale.state.active.All(p=>p.admitted||p.berth<0),"land reservations in old saves release immediately");
  var progress=new VoyageModel(cfg,new VoyageState{total=cfg.finalTotal,available=cfg.finalTotal,demon=3,crisis=2});Check(progress.CanSail&&progress.state.boarded==0,"contribution reaches ending without animal quota or protection purchase");progress.state.available=1;progress.state.spent=progress.state.total-1;Check(progress.CanSail,"spending never rolls back contribution progress");
  var guard=new VoyageModel(cfg);guard.state.levels[3]=1;var animal=guard.state.active[0];animal.x=guard.state.guideX;animal.y=guard.state.guideY;animal.calm=0;Check(guard.Shelter()&&guard.Protected(animal)&&animal.calm==0,"shelter protects without granting acceleration");animal.x=-.7f;Check(!guard.Protected(animal),"protection has local range");
  var flow=new VoyageModel(cfg);flow.state.area=2;flow.state.workers[0].rest=999;foreach(var p in flow.state.active){p.x=-.4f;p.y=.68f;p.life=50;p.calm=0;}flow.Tick(.1f);Check(flow.state.active.Take(3).All(p=>!p.heading),"old animals are not forced to ark by age");
  var boss=new VoyageModel(cfg);boss.state.demon=2;boss.state.demonHp=180;boss.state.demonX=.2f;boss.state.demonY=.6f;boss.state.bossX=.2f;boss.state.bossY=.6f;boss.state.attackClock=.1f;foreach(var p in boss.state.active){p.x=.2f;p.y=.6f;p.age=0;}long total=boss.state.total;boss.Tick(.2f);Check(boss.state.lost>0&&boss.state.total==total&&boss.state.lostValue>0,"AoE removes unboarded contribution only");for(int i=0;i<9;i++)boss.Pray(.1f);Check(boss.state.bossStun>0&&boss.state.demonHp<180&&boss.state.attackClock>1.5f,"holy damage interrupts attack and stuns");
  var strike=Stock(cfg,0);strike.state.demon=2;strike.state.demonHp=180;strike.state.demonX=strike.state.bossX=.2f;strike.state.demonY=strike.state.bossY=.6f;strike.state.attackClock=.01f;foreach(var p in strike.state.active){p.x=.2f;p.y=.6f;}long exposed=strike.state.active.Sum(p=>(long)p.reward);strike.Tick(.02f);Check(strike.state.lost==64,"every exposed animal inside the circle dies, without per-hit cap");Check(strike.state.lostValue==exposed-strike.state.active.Sum(p=>(long)p.reward)&&strike.state.total==0,"range deaths remove exactly their unearned contribution");
  var protectedStrike=Stock(cfg,0);protectedStrike.state.demon=2;protectedStrike.state.demonHp=180;protectedStrike.state.demonX=protectedStrike.state.bossX=.2f;protectedStrike.state.demonY=protectedStrike.state.bossY=.6f;protectedStrike.state.attackClock=.01f;protectedStrike.state.shelterTime=10;protectedStrike.state.shieldX=.02f;protectedStrike.state.shieldY=.6f;var safeIds=protectedStrike.state.active.Take(3).Select(p=>p.id).ToArray();foreach(var p in protectedStrike.state.active){p.x=safeIds.Contains(p.id)?.1f:.30f;p.y=.6f;}protectedStrike.state.active[3].x=.6f;long outsideId=protectedStrike.state.active[3].id;var boardedSafe=protectedStrike.state.active[4];boardedSafe.x=.2f;boardedSafe.admitted=true;boardedSafe.berth=0;boardedSafe.boarding=.2f;protectedStrike.Tick(.02f);Check(protectedStrike.state.active.Any(p=>p.id==outsideId)&&protectedStrike.state.active.Contains(boardedSafe),"outside-circle and already-boarding animals survive");Check(safeIds.All(id=>protectedStrike.state.active.Any(p=>p.id==id))&&protectedStrike.state.lost==59,"shelter saves its animals while all exposed targets die");
  var wider=Stock(cfg,0);wider.state.demon=2;wider.state.demonHp=180;wider.state.demonX=wider.state.bossX=.2f;wider.state.demonY=wider.state.bossY=.6f;wider.state.attackClock=.01f;foreach(var p in wider.state.active){p.x=.32f;p.y=.6f;}wider.Tick(.02f);Check(wider.state.lost==64,"expanded warning circle matches actual hit range");
  for(int hit=0;hit<8;hit++){strike.state.attackClock=999;while(strike.state.active.Count<24){strike.state.spawnClock=0;strike.Tick(.001f);}strike.state.spawnClock=999;foreach(var p in strike.state.active){p.admitted=false;p.berth=-1;p.age=0;p.x=.2f;p.y=.6f;}strike.state.bossX=.2f;strike.state.bossY=.6f;strike.state.attackClock=.01f;strike.Tick(.02f);}Check(strike.state.lost==256&&strike.state.active.Count==0,"later strikes remain lethal beyond the former total casualty cap");Check(VoyageModel.Validate(cfg,strike.state,out _),"stronger boss preserves exact payment ledger");
  report.AppendLine("Boss: all 64 exposed animals die in one strike; radius .24; shield/outside/boarding survivors verified; 256 cumulative deaths without immunity cap.");
  var background=new VoyageModel(cfg);background.state.lastUtc=1;Check(background.ApplyAway(1000)==0,"old save timestamp cannot create offline income");background.BeginBackground(1000);var before=background.state.active.Select(p=>VoyageModel.Position(p)).ToArray();long award=background.ApplyAway(1060);Check(award>0&&before.SequenceEqual(background.state.active.Select(p=>VoyageModel.Position(p))),"open background interval earns without animal simulation");Check(background.ApplyAway(1120)==0,"each background interval pays only once");background.BeginBackground(2000);var reopened=new VoyageModel(cfg,VoyageSave.Decode(cfg,VoyageSave.Encode(background.state)));Check(reopened.ApplyAway(2100)==0,"reopening a saved hidden tab does not award closed time");
  var cap=new VoyageModel(cfg,new VoyageState{total=1000000,available=1000000});cap.state.levels[2]=5;var sameProduction=new VoyageModel(cfg,new VoyageState{total=20000,available=20000});sameProduction.state.levels[2]=5;Check(cap.PassiveRate()>0&&Math.Abs(cap.PassiveRate()-sameProduction.PassiveRate())<.001f,"background baseline follows sustainable arrivals rather than stored wealth");
  var actual=new VoyageModel(cfg);for(int i=0;i<1200;i++)actual.Tick(.1f);float observed=actual.PassiveRate();actual.BeginBackground(3000);long safeAward=actual.ApplyAway(3060);Check(safeAward<=(long)Math.Ceiling(observed*60)&&Math.Abs(actual.PassiveRate()-observed)<.001f,"background uses frozen observed rate and cannot compound itself");
  var limited=Stock(cfg,0);limited.populationLimit=24;long next=limited.state.nextId;int existing=limited.state.active.Count;limited.Tick(.01f);Check(limited.state.nextId==next&&limited.state.active.Count==existing,"lower device budget pauses spawning without deleting existing animals");
  var endurance=new VoyageModel(cfg);endurance.populationLimit=24;endurance.state.active[0].age=-100000;bool enduranceBounded=true;for(int i=0;i<18000;i++){endurance.Tick(.1f);enduranceBounded&=endurance.state.active.Count<=24&&endurance.state.paidTail.Count==0;endurance.events.Clear();endurance.arrivals.Clear();endurance.scattered.Clear();}Check(enduranceBounded&&endurance.state.boarded>100,"30 minute run bounds population and ledger despite oldest animal remaining");Check(VoyageModel.Validate(cfg,endurance.state,out _),"bounded endurance ledger is valid");
  string compact=VoyageSave.Encode(endurance.state);var loaded=new VoyageModel(cfg,VoyageSave.Decode(cfg,compact));Check(loaded.state.total==endurance.state.total&&loaded.state.active.Count==endurance.state.active.Count,"compact ledger survives reload without lost progress");
  Check(VoyageModel.Validate(cfg,boss.state,out var why),"boss ledger "+why);
  report.AppendLine("PASS "+checks+" checks");Directory.CreateDirectory("../Evidence/V102");File.WriteAllText("../Evidence/V102/v10-verification.txt",report.ToString());Debug.Log(report);
 }
}
